$class_path = $library_directories

# Root of Project
$project_root = "F:\PROGRAMME\imitation\marshmallow"
$source_path  = "$project_root\src\main\java"
$resource_path = "$project_root\src\main\resources"
$output_directory = "$project_root\output"
$jar_output   = "$project_root\build\imitation-marshmallow-0.0.1.jar"

# ===== Clear the output directory =====
if (Test-Path $output_directory) { Remove-Item -Recurse -Force $output_directory }
New-Item -ItemType Directory -Force -Path $output_directory | Out-Null

# ===== Collect source codes =====
$java_files = Get-ChildItem -Path $source_path -Filter *.java -Recurse | ForEach-Object { $_.FullName }
if ($java_files.Count -eq 0) {
    Write-Error "No source files in $source_path"
    exit 1
}
$source_list = "$project_root\build\sources.txt"
New-Item -ItemType Directory -Force -Path "$project_root\build" | Out-Null
# $java_files | Set-Content -Path $source_list -Encoding UTF8
[System.IO.File]::WriteAllLines($source_list, $java_files, [System.Text.Encoding]::ASCII)

# ===== Compile =====
Write-Host "== Compiling ==" -ForegroundColor Cyan
& javac -encoding UTF-8 -d $output_directory -cp $class_path "@$source_list"
if ($LASTEXITCODE -ne 0) {
    Write-Error "Failed to compile: exited $LASTEXITCODE"
    exit $LASTEXITCODE
}
Write-Host "Succeed in compiling" -ForegroundColor Green

# ===== Copy resources =====
if (Test-Path $resource_path) {
    Copy-Item -Path "$resource_path\*" -Destination $output_directory -Recurse -Force
    Write-Host "Copied resources like fabric.mod.json"
}

# =====Package =====
Write-Host "== Packing ==" -ForegroundColor Cyan
if (Test-Path $jar_output) { Remove-Item -Force $jar_output }
& jar --create --file $jar_output -C $output_directory .
if ($LASTEXITCODE -ne 0) {
    Write-Error "Failed to pack: exited $LASTEXITCODE"
    exit $LASTEXITCODE
}
Write-Host "Succeed in packing $jar_output" -ForegroundColor Green